<template><view :data-skin="scenicSkin" class="visual-page safe journal"><TopBar :title="mode==='ecology'?'CR-07 生态档案':'青崖山 · 重建手记'" eyebrow="ONLY WHAT WE HAVE WITNESSED" @back="back" @settings="settings"/><view class="content"><text class="intro">{{mode==='ecology'?'只记录亲眼见过的生命与结构。未知不是敌意，也不是安全。':'把今天能做到的事，一件一件做完。各项指数为试玩中的建设状态，不代表实际库存。'}}</text><template v-if="mode==='ecology'"><view class="record-grid"><view v-for="o in observations" :key="o.id" class="record"><image v-if="s.evidenceIds.includes(o.id)" :src="sceneArt(o.scene)" mode="aspectFill"/><view v-else class="unknown">?</view><view class="record-copy"><text class="code">{{o.id}} / {{s.evidenceIds.includes(o.id)?'已目击':'未接触'}}</text><text class="name">{{s.evidenceIds.includes(o.id)?o.title:'等待亲自抵达'}}</text><text>{{s.evidenceIds.includes(o.id)?o.description:'CR-07 无法读取尚未接触的事物。'}}</text></view></view></view></template><template v-else><view class="metrics"><view v-for="r in resources" :key="r.id"><text>{{r.name}}</text><text>{{s.stats[r.id]}}<small> / 100</small></text><view class="meter"><view :style="{width:s.stats[r.id]+'%'}"/></view></view></view><text class="section-title">正在成为家的地方</text><view class="facilities"><AssetPanel v-for="f in facilities" :key="f.flag"><text class="code">EP. {{f.episode}}</text><text class="name">{{f.name}}</text><text>{{s.flags[f.flag]?'已完成 · 写入本周目':'待推进 · 随故事建设'}}</text></AssetPanel></view><AssetPanel v-if="s.flags.contractSigned" class="contract"><text class="name">合作商户 01 · 百鬼街商户联合体</text><text>47 家商户 / 1 个合作主体 · 实物与公共服务抵租</text></AssetPanel><text class="section-title">决定与回声</text><view v-for="h in [...s.choiceHistory].reverse()" :key="h.at+'-'+h.node" class="history"><text class="code">{{story[h.node]?.title}}</text><text class="name">{{h.text}}</text><text>{{story[h.node]?.choices?.find(c=>c.id===h.choice)?.outcome}}</text></view><text v-if="!s.choiceHistory.length" class="intro">从考场外出发，第一项决定正在等你。</text></template><AssetButton @click="play">{{s.hasSave?'继续旅程':'开启旅程'}}</AssetButton></view></view></template>
<script setup lang="ts">
import TopBar from './TopBar.vue';import AssetPanel from './common/AssetPanel.vue';import AssetButton from './common/AssetButton.vue';import {gameStore,storyEngine} from '../store/game';import {resources,facilities,observations} from '../data/scenic-progress';import {sceneArt} from '../data/backgrounds';import {story} from '../data/story';import {goBack} from '../utils/navigation';defineProps<{mode:'ecology'|'ledger'}>();const s=gameStore.state;function back(){goBack()}function settings(){uni.navigateTo({url:'/pages/settings/index'})}function play(){if(!s.hasSave)storyEngine.startNewGame();uni.reLaunch({url:'/pages/play/index'})}
</script>
<style scoped>.journal{background:var(--bg);color:var(--text)}.content{padding:10px 5vw 50px;max-width:1500px;margin:auto}.intro{display:block;color:var(--muted);font-size:14px;line-height:1.8;margin-bottom:30px}.record-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-bottom:30px}.record{border:1px solid var(--line);background:var(--panel)}.record image,.unknown{width:100%;height:190px}.unknown{display:flex;align-items:center;justify-content:center;background:var(--panel-2);font:65px serif;color:var(--muted)}.record-copy{padding:22px;font-size:13px;line-height:1.8}.code{display:block;font:10px/1.8 sans-serif;letter-spacing:2px;color:var(--gold)}.name{display:block;font:20px/1.6 serif;margin:6px 0 12px}.metrics{display:grid;grid-template-columns:repeat(6,1fr);gap:20px}.metrics>view{padding:20px;border:1px solid var(--line)}.metrics text{display:block;font-size:13px}.metrics text+text{font:30px/1.8 Georgia}.metrics small{font:11px sans-serif;color:var(--muted)}.meter{height:3px;background:var(--line)}.meter>view{height:100%;background:var(--gold)}.section-title{display:block;font:25px serif;margin:35px 0 20px}.facilities{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.facilities text:last-child,.contract text:last-child{font-size:12px;color:var(--muted)}.history{padding:20px 0;border-bottom:1px solid var(--line);font-size:13px;line-height:1.8}.history:last-of-type{margin-bottom:25px}.contract{margin-top:25px}@media(max-width:800px){.record-grid,.facilities{grid-template-columns:1fr 1fr}.metrics{grid-template-columns:repeat(3,1fr)}.name{font-size:18px}}@media(max-width:480px){.record-grid{grid-template-columns:1fr}.metrics{gap:8px}.metrics>view{padding:14px}.facilities{grid-template-columns:1fr}.content{padding:10px 22px 35px}}</style>
